input.command:
cd /tmp/probe/imports-order/base && R(){ echo "##### $*"; /workspace/executable "$@" >/tmp/probe/imports-order/o 2>/dev/null; echo "EXIT=$?"; cat -A /tmp/probe/imports-order/o; }
cat > p.go <<'EOF'
package base

import (
	// leading comment for blank
	_ "github.com/blank1" // trailing blank
	"fmt"
	// leading for dot
	. "github.com/dot1"
)
EOF
R -output stdout -imports-order std,general,company,project p.go
R -output stdout -imports-order std,general,company,project,blanked,dotted p.go
cat > q.go <<'EOF'
package base

import (
	"log"
	_ "github.com/b1"
)

import (
	"fmt"
	. "github.com/d1"
)
EOF
R -output stdout -imports-order std,general,company,project q.go
R -output stdout -imports-order std,general,company,project,blanked,dotted q.go
